      keep(x, {t: te ? plain(te) : "", py: hd && hd.dataset.py || "", g: ge ? ge.textContent : "", sd: kp.dataset.cgsd != null ? +kp.dataset.cgsd : undefined, via: "card"}); kp.textContent = "✓ " + T("收好了", "Kept"); kp.disabled = true; fx(kp);
