/* ── 打开小卡：电脑上从右边滑出，手机上从底下拉起 ── */
function css(){ if (document.getElementById("cgCss")) return; const s = document.createElement("style"); s.id = "cgCss"; s.textContent = CSS; document.head.appendChild(s); }
function close(){ stopSay(); const w = document.getElementById("cgWrap"); if (!w) return; w.classList.remove("on"); setTimeout(() => w.remove(), 220); }
function open(id, o){ o = o || {}; const x = item(id); if (!x) return false; css(); close();
  const w = document.createElement("div"); w.id = "cgWrap"; w.className = "cg-wrap" + (matchMedia("(min-width:861px)").matches ? " cg-side" : "");
  w.dataset.nopy = ""; w.innerHTML = `<div class="cg-dim"></div><div class="cg-sheet" role="dialog" aria-modal="true"><div class="cg-grab"></div><button class="cg-x" aria-label="${esc(T("关上", "Close"))}">✕</button><div class="cg-in">${cardInner(x, o)}</div></div>`;
  document.body.appendChild(w); requestAnimationFrame(() => w.classList.add("on"));
  w.querySelector(".cg-dim").onclick = close; w.querySelector(".cg-x").onclick = close;
  wireCard(w.querySelector(".cg-in"), x, o);
  const st = ST(); st.o[id] = (st.o[id] || 0) + 1; SAVE(st); seen(id);
  return true; }
// 动态里的线：点了打开小卡。挂在 window 的捕获阶段（最早），别让动态本身的点按也跑（朋友墙的点按挂在 document 的捕获阶段）
window.addEventListener("click", e => { const u = e.target.closest && e.target.closest(".cg-ul"); if (!u) return; e.stopPropagation(); e.preventDefault();
  open(u.dataset.cg, {who: u.dataset.cgw || "", key: u.dataset.cgk || "", quoted: u.dataset.cgq === "1"});
  document.querySelectorAll(`.cg-ul[data-cg="${window.CSS.escape(u.dataset.cg)}"]`).forEach(z => z.classList.add("cg-was")); }, true);
document.addEventListener("keydown", e => { if (e.key === "Escape" && document.getElementById("cgWrap")) close(); const u = e.target.closest && e.target.closest(".cg-ul"); if (u && (e.key === "Enter" || e.key === " ")){ e.preventDefault(); u.click(); } });

/* ── 话题第一屏：先递一样东西，再进原来的题 ──
 * 同一个话题一天只递一次；没有对得上的、都看过三次了，就直接进。 */
function gate(isle, k, go){ try {
  const key = isle + "." + k, st = ST(), day = today(); if (st.g[key] === day) return false;
  const lv = level();
  const x = pick({topic: key, level: lv}); if (!x) return false;
  css(); st.g[key] = day; SAVE(st); seen(x.id);
  const w = document.createElement("div"); w.id = "cgGate"; w.className = "cg-gate"; w.dataset.nopy = "";
  w.innerHTML = `<div class="cg-gcard" role="dialog" aria-modal="true"><button class="cg-x" aria-label="${esc(T("关上", "Close"))}">✕</button><div class="cg-gk" dir="auto">${esc(T("聊这个之前，先给你一样东西", "Before we start — something for you"))}</div><div class="cg-in">${cardInner(x, {})}</div>
    <button class="cg-go">${esc(T("接着聊 →", "Let's go →"))}</button></div>`;
  document.body.appendChild(w); requestAnimationFrame(() => w.classList.add("on"));
  wireCard(w.querySelector(".cg-in"), x, {});
  const fin = run => { stopSay(); w.classList.remove("on"); setTimeout(() => w.remove(), 200); if (run) try { go(); } catch(e){} };
  w.querySelector(".cg-go").onclick = e => { fx(e.currentTarget); fin(true); };
  w.querySelector(".cg-x").onclick = () => fin(true);
  return true; } catch(e){ try { console.warn("[社会文化] 话题第一屏出错，直接进话题", e); } catch(_){} return false; } }

